using System.Drawing.Drawing2D;
using System.Runtime.InteropServices;

namespace ScreenShare;

/// <summary>
/// Draws the tray/window icon at runtime so it can add a green dot while sharing.
/// The exe's embedded icon (app.ico) is the version without the dot, generated by tools/New-AppIcon.ps1; keep them in sync.
/// </summary>
internal static class AppIcon
{
    [DllImport("user32.dll")]
    private static extern bool DestroyIcon(IntPtr handle);

    public static Icon Create(bool live)
    {
        using var bmp = new Bitmap(32, 32);
        using (var g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.Clear(Color.Transparent);

            // A dark monitor outline with a filled light blue "screen".
            using var frame = new SolidBrush(Color.FromArgb(36, 41, 47));
            using var screen = new SolidBrush(Color.FromArgb(96, 178, 245));
            using var stand = new SolidBrush(Color.FromArgb(36, 41, 47));
            g.FillRectangle(frame, 1, 3, 30, 21);
            g.FillRectangle(screen, 3, 5, 26, 17);
            g.FillRectangle(stand, 13, 24, 6, 3);
            g.FillRectangle(stand, 9, 27, 14, 3);

            // Sharing is shown by the same dot as the taskbar badge, in the top-right corner.
            if (live)
                DrawLiveDot(g, 16, 0, 16);
        }

        return ToIcon(bmp);
    }

    /// <summary>The green dot laid over the taskbar button while sharing is live.</summary>
    public static Icon CreateLiveBadge()
    {
        using var bmp = new Bitmap(16, 16);
        using (var g = Graphics.FromImage(bmp))
        {
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.Clear(Color.Transparent);
            DrawLiveDot(g, 0, 0, 16);
        }
        return ToIcon(bmp);
    }

    /// <summary>A green dot with a white ring, filling a size×size square at x, y.</summary>
    private static void DrawLiveDot(Graphics g, float x, float y, float size)
    {
        using var outline = new SolidBrush(Color.White);
        using var dot = new SolidBrush(Color.FromArgb(46, 160, 67));
        float ring = size / 8;
        g.FillEllipse(outline, x, y, size - 1, size - 1);
        g.FillEllipse(dot, x + ring, y + ring, size - 1 - 2 * ring, size - 1 - 2 * ring);
    }

    private static Icon ToIcon(Bitmap bmp)
    {
        IntPtr handle = bmp.GetHicon();
        try
        {
            return (Icon)Icon.FromHandle(handle).Clone();
        }
        finally
        {
            DestroyIcon(handle);
        }
    }
}
